script:
(() => {
	const init = () => {
		const page = document.querySelector(".st-page");
		const onCatalogue = page && page.classList.contains("st-page-home");
		const markNav = (key) => document.querySelectorAll(".st-nav").forEach((a) => a.classList.toggle("st-on", a.classList.contains(`st-k-${key}`)));
		const filter = (key) => {
			let shown = 0;
			document.querySelectorAll(".st-grid .st-card").forEach((card) => {
				card.hidden = key !== "all" && !card.classList.contains(`st-${key}`);
				if (!card.hidden) shown++;
			});
			document.querySelectorAll(".st-tab").forEach((t) => t.classList.toggle("st-on", t.getAttribute("href") === `#${key}` || (key !== "new" && key !== "best" && t.getAttribute("href") === "#all")));
			const count = document.querySelector(".st-count");
			if (count) count.textContent = `${shown} objects`;
			markNav(key);
		};
		if (onCatalogue) {
			document.querySelectorAll(".st-nav, .st-tab").forEach((a) => a.addEventListener("click", (event) => {
				const href = a.getAttribute("href");
				if (!href.includes("#") && href !== "home") return;
				event.preventDefault();
				const key = href.includes("#") ? href.split("#")[1] : "all";
				history.replaceState(null, "", key === "all" ? location.pathname : `#${key}`);
				filter(key);
			}));
			filter(location.hash.slice(1) || "all");
		} else {
			markNav(page && page.classList.contains("st-page-list") ? "list" : "paper");
		}
		document.querySelectorAll(".st-seg").forEach((seg) => seg.querySelectorAll(".st-opt").forEach((opt) => opt.addEventListener("click", () => {
			seg.querySelectorAll(".st-opt").forEach((o) => o.classList.toggle("st-on", o === opt));
		})));
		document.querySelectorAll(".st-switch").forEach((s) => s.addEventListener("click", () => s.classList.toggle("st-on")));
		document.querySelectorAll(".st-check").forEach((c) => c.addEventListener("click", () => c.classList.toggle("st-on")));
		const value = document.querySelector(".st-step-value");
		const step = (d) => { if (value) value.textContent = Math.max(1, Number(value.textContent) + d); };
		document.querySelectorAll(".st-step-minus").forEach((b) => b.addEventListener("click", () => step(-1)));
		document.querySelectorAll(".st-step-plus").forEach((b) => b.addEventListener("click", () => step(1)));
	};
	document.readyState === "loading" ? document.addEventListener("DOMContentLoaded", init) : init();
})();
